from datetime import date, timedelta

class Loan:
    PERIOD = timedelta(days=14)
    def __init__(self, copy, member, today):
        self.copy, self.member = copy, member
        self.due = today + Loan.PERIOD

    def is_overdue(self, today):
        return today > self.due

class Library:
    def __init__(self):
        self.copies = {}           # isbn -> list of BookCopy

    def checkout(self, isbn, member, today):
        if len(member.loans) >= member.policy.max_loans:
            raise ValueError("loan limit reached")
        for copy in self.copies.get(isbn, []):
            if copy.loan is None:
                copy.loan = Loan(copy, member, today)
                member.loans.append(copy.loan)
                return copy.loan
        return None                # none free: offer a hold

class Node:
    def __init__(self, key=None, value=None):
        self.key, self.value = key, value
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.nodes = {}                         # key -> Node
        self.head, self.tail = Node(), Node()   # sentinels
        self.head.next, self.tail.prev = self.tail, self.head

    def _unlink(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _push_front(self, node):                # most recently used
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key, default=None):
        node = self.nodes.get(key)
        if node is None:
            return default
        self._unlink(node)
        self._push_front(node)                  # reading is a use
        return node.value

    def put(self, key, value):
        if key in self.nodes:
            self._unlink(self.nodes[key])
        node = Node(key, value)
        self.nodes[key] = node
        self._push_front(node)
        if len(self.nodes) > self.capacity:
            lru = self.tail.prev                # least recently used
            self._unlink(lru)
            del self.nodes[lru.key]

