from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()           # oldest first

    def get(self, key, default=None):
        if key not in self.data:
            return default
        return self.data[key]               # bug: not marked as recent

    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)          # newest at the end
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)   # drop the oldest

cache = LRUCache(2)
cache.put("a", 1)
cache.put("b", 2)
cache.get("a")
cache.put("c", 3)
print(cache.get("b"), cache.get("a"), cache.get("c"))

